items.css_text:
        .material-symbols-outlined {
            font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
        }
        .connection-line {
            position: absolute;
            background-color: theme('colors.operational-blue');
            opacity: 0.3;
            transition: all 0.5s ease-in-out;
        }
        .connection-line-anim {
            animation: pulse-line 2s infinite;
        }
        @keyframes pulse-line {
            0% { opacity: 0.1; }
            50% { opacity: 0.8; }
            100% { opacity: 0.1; }
        }
        .bento-card {
            background-color: theme('colors.surface-container-lowest');
            border: 1px solid theme('colors.border-subtle');
            border-radius: theme('borderRadius.xl');
            transition: all 0.3s ease;
        }
        .bento-card:hover {
            box-shadow: 0px 4px 20px rgba(0,0,0,0.05);
            transform: translateY(-2px);
        }

        /* Interactive Nav Rails */
        .scenario-tab {
            cursor: pointer;
            transition: all 0.2s ease;
            border-left: 2px solid transparent;
        }
        .scenario-tab.active {
            border-left-color: theme('colors.primary');
            background-color: theme('colors.primary/5');
        }
        .scenario-tab.active .tab-title {
            color: theme('colors.primary');
            font-weight: 600;
        }

        .scenario-content {
            display: none;
            opacity: 0;
            transition: opacity 0.3s ease;
        }
        .scenario-content.active {
            display: block;
            opacity: 1;
        }

